"""Generate the small embedded ASCII font used by the SDL chat windows."""

from pathlib import Path

from PIL import Image, ImageDraw, ImageFont


WIDTH = 10
HEIGHT = 12
font = ImageFont.load_default()
rows = []
for codepoint in range(32, 127):
    image = Image.new("L", (WIDTH, HEIGHT), 0)
    ImageDraw.Draw(image).text((0, -1), chr(codepoint), font=font, fill=255)
    rows.append([sum(1 << x for x in range(WIDTH) if image.getpixel((x, y)) >= 96) for y in range(HEIGHT)])

output = Path(__file__).resolve().parents[1] / "src/ui/bitmap_font.h"
lines = [
    "// Generated by tools/generate_bitmap_font.py from Pillow's default Aileron font.",
    "#pragma once",
    "#include <cstdint>",
    "namespace BitmapFont {",
    f"constexpr int WIDTH = {WIDTH};",
    f"constexpr int HEIGHT = {HEIGHT};",
    "constexpr std::uint16_t GLYPHS[95][HEIGHT] = {",
]
for codepoint, glyph in enumerate(rows, start=32):
    values = ", ".join(f"0x{value:03x}" for value in glyph)
    lines.append(f"    {{{values}}}, // {codepoint}")
lines += ["};", "}"]
output.write_text("\n".join(lines) + "\n")
